function toPrimitiveDefault(obj) {
  const v = obj.valueOf();
  if (v === null || (typeof v !== 'object' && typeof v !== 'function')) return v;
  const s = obj.toString();
  if (s === null || (typeof s !== 'object' && typeof s !== 'function')) return s;
  throw new TypeError('Cannot convert object to primitive value');
}

function miniLooseEqual(a, b) {
  const ta = typeof a;
  const tb = typeof b;
  if (ta === tb) return a === b;
  if ((a === null && b === undefined) || (a === undefined && b === null)) return true;
  if (ta === 'boolean') return miniLooseEqual(Number(a), b);
  if (tb === 'boolean') return miniLooseEqual(a, Number(b));
  if (ta === 'number' && tb === 'string') return miniLooseEqual(a, Number(b));
  if (ta === 'string' && tb === 'number') return miniLooseEqual(Number(a), b);
  if ((ta === 'string' || ta === 'number') && b !== null && (tb === 'object' || tb === 'function')) {
    return miniLooseEqual(a, toPrimitiveDefault(b));
  }
  if ((tb === 'string' || tb === 'number') && a !== null && (ta === 'object' || ta === 'function')) {
    return miniLooseEqual(toPrimitiveDefault(a), b);
  }
  return false;
}

console.log(miniLooseEqual('0', false));
console.log(miniLooseEqual([], 0));
console.log(miniLooseEqual(null, 0));
console.log(miniLooseEqual('5', 5));
console.log(miniLooseEqual({}, '[object Object]'));
console.log(miniLooseEqual(NaN, NaN));

